using System.Collections.Generic;

namespace ProjectTower.settings;

public class Stats
{
	public class SteamStat
	{
		public string statName;

		public string win;

		public string loss;

		public int wins;

		public int losses;

		public int value;

		public int type;

		public const int TYPE_NORMAL = 0;

		public const int TYPE_BOSS = 1;

		public SteamStat(string p, int type)
		{
			statName = p;
			this.type = type;
			if (type == 1)
			{
				win = p + "_WIN";
				loss = p + "_LOSS";
			}
			value = 0;
			wins = 0;
			losses = 0;
		}
	}

	public const int DEATHS = 0;

	public const int BOSS_KILLS = 1;

	public static Dictionary<string, SteamStat> stats;

	public static readonly string[] statName = new string[2] { "DEATHS", "BOSS_KILLS" };

	public static bool inited;

	internal static void AddBoss(string p)
	{
		if (!inited && p.StartsWith("boss "))
		{
			string text = p.Substring("boss ".Length).ToUpper();
			AddStat(p, text, 1);
		}
	}

	internal static void Init()
	{
		if (!inited)
		{
			stats = new Dictionary<string, SteamStat>();
			AddStat("deaths", "DEATHS", 0);
			AddStat("boss_kills", "BOSS_KILLS", 0);
		}
	}

	internal static void AddStat(string friendlyName, string statName, int type)
	{
		if (!stats.ContainsKey(friendlyName))
		{
			stats.Add(friendlyName, new SteamStat(statName, type));
		}
	}

	internal static float GetBossProg(string p)
	{
		if (stats.ContainsKey(p))
		{
			return (float)stats[p].wins / ((float)stats[p].losses + (float)stats[p].wins);
		}
		return 0f;
	}

	internal static void Finalize()
	{
		inited = true;
	}
}
