namespace ProjectTower.storage;

public class StorageJobMgr
{
	private static List<StorageJob> storageJob;

	public static bool busy;

	public static bool jobWorking;

	public static int topJob;

	public static float TIME_OUT_MAX = 2f;

	public static float timeOut;

	public const int TIMEOUT_TICKS = 1000;

	public static StringBuilder jobSemaphore;

	private const bool THREADED = true;

	public static void Init()
	{
		jobSemaphore = new StringBuilder("semaphore");
		storageJob = new List<StorageJob>();
		StorageJob.MigrateSaves();
	}

	public static void AddJob(int job, int playerIdx, int dataIdx, Player player, CharEquipment charEquipment)
	{
		StorageJob item = new StorageJob(job, playerIdx, dataIdx, player, charEquipment);
		storageJob.Add(item);
	}

	public static void AddJob(int job, int playerIdx, int dataIdx)
	{
		StorageJob item = new StorageJob(job, playerIdx, dataIdx);
		storageJob.Add(item);
	}

	public static void AddJob(int job, int playerIdx)
	{
		StorageJob item = new StorageJob(job, playerIdx, -1);
		storageJob.Add(item);
	}

	public static void Update(float frameTime)
	{
		if (timeOut > 0f)
		{
			timeOut -= frameTime;
		}
		if (StorageJobMgr.storageJob.Count > 0)
		{
			topJob = StorageJobMgr.storageJob[0].job;
			busy = true;
			StorageJob storageJob = new StorageJob(StorageJobMgr.storageJob[0]);
			StorageJobMgr.storageJob.RemoveAt(0);
			storageJob.Work();
		}
		if (ConfigMgr.newConfig)
		{
			ConfigMgr.newConfig = false;
			ConfigMgr.Write();
		}
	}

	public static int GetJobCount()
	{
		return storageJob.Count;
	}
}
